class Solution:
    def checkPartitioning(self, s: str) -> bool:
        def is_pal(i, j):
            while i < j:
                if s[i] != s[j]:
                    return False
                i += 1
                j -= 1
            return True

        n = len(s)
        for i in range(1, n - 1):
            if not is_pal(0, i - 1):
                continue
            for j in range(i, n - 1):
                if is_pal(i, j) and is_pal(j + 1, n - 1):
                    return True
        return False

