class Solution {
public:
    bool checkPartitioning(string s) {
        int n = s.size();
        auto isPal = [&](int i, int j) {
            while (i < j) {
                if (s[i] != s[j]) return false;
                i++; j--;
            }
            return true;
        };
        for (int i = 1; i < n - 1; i++) {
            if (!isPal(0, i - 1)) continue;
            for (int j = i; j < n - 1; j++) {
                if (isPal(i, j) && isPal(j + 1, n - 1)) return true;
            }
        }
        return false;
    }
};

