class Solution {
    public boolean checkPartitioning(String s) {
        int n = s.length();
        for (int i = 1; i < n - 1; i++) {
            if (!isPal(s, 0, i - 1)) continue;
            for (int j = i; j < n - 1; j++) {
                if (isPal(s, i, j) && isPal(s, j + 1, n - 1)) return true;
            }
        }
        return false;
    }

    private boolean isPal(String s, int i, int j) {
        while (i < j) {
            if (s.charAt(i) != s.charAt(j)) return false;
            i++; j--;
        }
        return true;
    }
};

